1	/**
2	 * `?match05=1&m05far=1` — Screen 05 round 7 (line B, qa/match/05/NOTES.md "Round 7"): the far forced-perspective tunnel
3	 * of Screen 05 (environment.ts `// ---- 05 far tunnel`, tube.ts ForcedTunnel) recalibrated to the LIVE camera every
4	 * frame instead of folding away.
5	 *
6	 * Why: the far block (rings C … G, the far S-river, the warm throat) is a depth compression along the eye rays of the
7	 * LOCKED checkpoint eye. From ≈34 u before its seam (sF05) it folded away (`openFor`), so from ≈20 u into the stage the
8	 * camera saw the far rings / river morphing out and the 06 arch hall behind them — the "old pink default world" of
9	 * the lead's audit (t66 / t95 frames). The compression is exact for ANY eye position once its two eye-dependent
10	 * constants (D0 = eye depth of the seam, q = eye offset from the axis) follow the eye, so under this switch:
11	 *   * the VIRTUAL tunnel (virtual depth Z beyond sF05, tunnel coordinate v = sF05 + u(Z)) stays put — rings, wall rows,
12	 *     the baked far water F and the far river layout are anchored to it, so everything approaches like real geometry;
13	 *   * the seam slides ahead of the eye so it never comes nearer than the locked view had it (D0lock ≈ 53 u): the part
14	 *     of the virtual tunnel between sF05 and the seam is drawn at REAL scale (k = 1) on the same straight axis (it
15	 *     covers the 05 → 06 flare), capped at `zCap` (just past the 06 start: the 06 river must not climb inside it);
16	 *   * the far river starts AT the seam (the real ribbon carries the course, coins and Benny before it);
17	 *   * only at the very end of the stage (eye ≤ ~11 u from the capped seam) the block folds away as before, into 06.
18	 * Default build and `?match05=1` without `m05far`: this file is never called (environment.ts keeps `openFor`).
19	 */
20	import * as THREE from 'three';
21	import type { ForcedTunnel, TubeWarp } from './tube';
22	import { tubeCenterAt } from './tube';
23	import type { FarRiverLayout, FarRiverRow } from './far05';
24	import { EDGE_LIFT, MATCH05, flag05, m05seam } from '../vfx/waterRibbon';
25	import { clip05 } from '../vfx/clip05';
26	
27	export const M05FAR: boolean = MATCH05 && flag05('m05far');
28	
29	type Item = { u: number; o: THREE.Vector3; basis: THREE.Matrix4; s: THREE.Vector3; openPos: THREE.Vector3; openScale: number };
30	
31	export interface LiveFar05Args {
32	  ft: ForcedTunnel;
33	  farWall: THREE.Mesh;
34	  farRiver: THREE.Mesh;
35	  farRings: THREE.InstancedMesh;
36	  farLids: THREE.InstancedMesh;
37	  ringItems: Item[];
38	  lidItems: Item[];
39	  glow: THREE.Mesh;
40	  glowMat: THREE.ShaderMaterial;
41	  lay: FarRiverLayout;
42	  level: number;
43	  zEnd: number;
44	  warp?: TubeWarp;
45	  /** wall build parameters (as ft.geometry(radial, steps, inset)) */
46	  radial: number; wallSteps: number; inset: number;
47	  /** river build parameters (as farRiverGeometry(cols, steps)) */
48	  cols: number; riverSteps: number;
49	  /** largest real extension beyond sF05 (units) */
50	  zCap: number;
51	  /** fold window: eye → seam distance (units) */
52	  foldNear: number; foldFar: number;
53	  /** the real course's height above the axis at real distance z beyond sF05 (the far water meets it at the seam) */
54	  riverUp: (z: number) => number;
55	}
56	
57	const ROW_KEYS: (keyof FarRiverRow)[] = ['xB', 'hw', 'cL', 'wL', 'cR', 'wR', 'core'];
58	
59	/** returns sync(cam): call from every far part's onBeforeRender */
60	export function createLiveFar05(a: LiveFar05Args): (cam: THREE.Camera) => void {
61	  const { ft } = a;
62	  const L = ft.L, c0 = ft.c0, T = ft.T, U = ft.U, Rt = ft.Rt, R = ft.R, sF = ft.sF;
63	  const D0lock = ft.D0;
64	  // the river layout depends on Z only: tabulate it once (dense near the seam) and interpolate
65	  const NT = 2400;
66	  const tz = new Float64Array(NT + 1), tr = new Float64Array((NT + 1) * ROW_KEYS.length);
67	  for (let n = 0; n <= NT; n++) {
68	    const Z = a.zEnd * (n / NT) ** 2;
69	    tz[n] = Z;
70	    const r = a.lay.row(Z);
71	    ROW_KEYS.forEach((k, i) => { tr[n * ROW_KEYS.length + i] = r[k]; });
72	  }
73	  const rowAt = (Z: number): FarRiverRow => {
74	    const f = Math.sqrt(Math.min(1, Math.max(0, Z / a.zEnd))) * NT;
75	    const n = Math.min(NT - 1, Math.floor(f)), w = f - n;
76	    const o = {} as FarRiverRow;
77	    ROW_KEYS.forEach((k, i) => { o[k] = tr[n * ROW_KEYS.length + i] * (1 - w) + tr[(n + 1) * ROW_KEYS.length + i] * w; });
78	    return o;
79	  };
80	
81	  // live state
82	  let D0 = D0lock, zs = 0;
83	  const q = new THREE.Vector3();
84	  const zOf = (Z: number) => (Z <= zs ? Z : zs + (Z - zs) / (1 + (Z - zs) / L));
85	  const kOf = (Z: number) => (D0 + zOf(Z)) / (D0 + Z);
86	  const cOf = (Z: number) => { if (Z <= zs) return 1; const b = 1 + (Z - zs) / L; return 1 / (b * b); };
87	  const tmp = new THREE.Vector3();
88	  const point = (Z: number, o: THREE.Vector3, out: THREE.Vector3) => {
89	    const k = kOf(Z);
90	    return out.copy(c0).addScaledVector(T, zOf(Z)).add(q).addScaledVector(tmp.copy(o).sub(q), k);
91	  };
92	
93	  // originals, restored whenever the eye is back at the locked checkpoint eye (the locked view stays bit-identical)
94	  const wg = a.farWall.geometry, rg = a.farRiver.geometry;
95	  const keep = (g: THREE.BufferGeometry, names: string[]) => names.map((n) => (g.getAttribute(n).array as Float32Array).slice());
96	  const wallNames = ['position', 'uv', 'fgExtra'];
97	  const wallOrig = keep(wg, wallNames);
98	  const wallOpenOrig = (wg.morphAttributes.position[0].array as Float32Array).slice();
99	  const rivNames = ['position', 'uv', 'aRivLat', 'aRivA', 'aRivB', 'fgExtra'];
100	  const rivOrig = keep(rg, rivNames);
101	  const rivOpenOrig = (rg.morphAttributes.position[0].array as Float32Array).slice();
102	  const eyeLock = c0.clone().addScaledVector(T, -D0lock).add(ft.q);
103	  const glowPos0 = a.glow.position.clone(), glowScale0 = a.glow.scale.x;
104	
105	  const restore = () => {
106	    wallNames.forEach((n, i) => { (wg.getAttribute(n).array as Float32Array).set(wallOrig[i]); wg.getAttribute(n).needsUpdate = true; });
107	    (wg.morphAttributes.position[0].array as Float32Array).set(wallOpenOrig); wg.morphAttributes.position[0].needsUpdate = true;
108	    rivNames.forEach((n, i) => { (rg.getAttribute(n).array as Float32Array).set(rivOrig[i]); rg.getAttribute(n).needsUpdate = true; });
109	    (rg.morphAttributes.position[0].array as Float32Array).set(rivOpenOrig); rg.morphAttributes.position[0].needsUpdate = true;
110	    a.glow.position.copy(glowPos0); a.glow.scale.setScalar(glowScale0);
111	  };
112	
113	  const d = new THREE.Vector3(), o = new THREE.Vector3(), p = new THREE.Vector3(), cr = new THREE.Vector3();
114	  const wv = new THREE.Vector2();
115	  const rowZ = (i: number, steps: number, zFrom: number) => {
116	    // uniform in projected radius (1/D), as ForcedTunnel.geometry
117	    const t = i / steps, Da = D0 + zFrom;
118	    const Dv = 1 / (1 / Da - t * (1 / Da - 1 / (D0 + a.zEnd)));
119	    return Math.max(zFrom, Dv - D0);
120	  };
121	  const fillWall = () => {
122	    const pos = wg.getAttribute('position').array as Float32Array, uv = wg.getAttribute('uv').array as Float32Array;
123	    const ext = wg.getAttribute('fgExtra').array as Float32Array, opn = wg.morphAttributes.position[0].array as Float32Array;
124	    const r0 = R * (1 - a.inset);
125	    for (let i = 0; i <= a.wallSteps; i++) {
126	      const Z = rowZ(i, a.wallSteps, 0), z = zOf(Z), sReal = sF + z;
127	      const fr = ft.path.frame(sReal);
128	      tubeCenterAt(ft.path, sReal, cr);
129	      const rOpen = ft.path.radius(sReal) * 1.1 + 0.4;
130	      const vv = sF + ft.uOfZ(Z);
131	      for (let j = 0; j <= a.radial; j++) {
132	        const th = -1.5 * Math.PI + (j / a.radial) * Math.PI * 2;
133	        d.copy(Rt).multiplyScalar(Math.cos(th)).addScaledVector(U, Math.sin(th));
134	        o.copy(d).multiplyScalar(r0);
135	        if (a.warp) { a.warp(Z, th, wv); o.addScaledVector(Rt, wv.x).addScaledVector(U, wv.y); }
136	        point(Z, o, p);
137	        const k = i * (a.radial + 1) + j;
138	        p.toArray(pos, k * 3);
139	        uv[k * 2 + 1] = vv;
140	        ext[k] = Z - z;
141	        o.copy(fr.right).multiplyScalar(Math.cos(th)).addScaledVector(fr.up, Math.sin(th)).multiplyScalar(rOpen).add(cr);
142	        o.toArray(opn, k * 3);
143	      }
144	    }
145	    for (const n of wallNames) wg.getAttribute(n).needsUpdate = true;
146	    wg.morphAttributes.position[0].needsUpdate = true;
147	  };
148	  const fillRiver = () => {
149	    const pos = rg.getAttribute('position').array as Float32Array, uv = rg.getAttribute('uv').array as Float32Array;
150	    const lat = rg.getAttribute('aRivLat').array as Float32Array, A = rg.getAttribute('aRivA').array as Float32Array;
151	    const B = rg.getAttribute('aRivB').array as Float32Array, ext = rg.getAttribute('fgExtra').array as Float32Array;
152	    const opn = rg.morphAttributes.position[0].array as Float32Array;
153	    const bank = 3, per = a.cols + 1 + 2 * bank, ch = a.lay.chord;
154	    for (let i = 0; i <= a.riverSteps; i++) {
155	      // the far river starts AT the seam: before it the real ribbon carries the course
156	      const Z = rowZ(i, a.riverSteps, zs), z = zOf(Z), sReal = sF + z;
157	      const fr = ft.path.frame(sReal);
158	      tubeCenterAt(ft.path, sReal, cr);
159	      const rr = ft.path.radius(sReal);
160	      const r = rowAt(Z);
161	      // lift to the real river where the seam has slid (the real ribbon starts climbing toward 06 there): 0 at zs = 0
162	      const lift = zs > 0 ? a.riverUp(Math.min(Z, zs)) - a.riverUp(0) : 0;
163	      const e0 = Math.max(-ch + 0.05, r.xB - r.hw), e1 = Math.min(ch - 0.05, r.xB + r.hw);
164	      const vv = sF + ft.uOfZ(Z);
165	      for (let j = 0; j < per; j++) {
166	        let x: number, h: number;
167	        if (j < bank) { const f = j / bank; x = -ch + (e0 + ch) * f; h = EDGE_LIFT + 0.1 * Math.sin(Math.PI * f); }
168	        else if (j > bank + a.cols) { const f = (j - bank - a.cols) / bank; x = e1 + (ch - e1) * f; h = EDGE_LIFT + 0.1 * Math.sin(Math.PI * f); }
169	        else {
170	          const f = (j - bank) / a.cols; x = e0 + (e1 - e0) * f;
171	          const u = Math.min(1, Math.abs(x - r.xB) / Math.max(0.5, r.hw));
172	          h = EDGE_LIFT * u * u * u;
173	        }
174	        o.copy(Rt).multiplyScalar(x).addScaledVector(U, a.level + h + lift);
175	        point(Z, o, p);
176	        const k = i * per + j;
177	        p.toArray(pos, k * 3);
178	        uv[k * 2] = (x + ch) / (2 * ch); uv[k * 2 + 1] = vv;
179	        lat[k] = x;
180	        A[k * 4] = r.xB; A[k * 4 + 1] = r.hw; A[k * 4 + 2] = r.cL; A[k * 4 + 3] = r.cR;
181	        B[k * 4] = r.wL; B[k * 4 + 1] = r.wR; B[k * 4 + 2] = r.core; B[k * 4 + 3] = Z;
182	        ext[k] = Z - z;
183	        o.copy(cr).addScaledVector(fr.right, x * (rr / R)).addScaledVector(fr.up, -rr - 0.6);
184	        o.toArray(opn, k * 3);
185	      }
186	    }
187	    for (const n of rivNames) rg.getAttribute(n).needsUpdate = true;
188	    rg.morphAttributes.position[0].needsUpdate = true;
189	  };
190	  const m = new THREE.Matrix4(), A4 = new THREE.Matrix4(), S4 = new THREE.Matrix4();
191	  const place = (mesh: THREE.InstancedMesh, items: Item[], open: number) => {
192	    const ext = mesh.geometry.getAttribute('fgExtra') as THREE.InstancedBufferAttribute | undefined;
193	    items.forEach((it, i) => {
194	      const Z = ft.zOfU(it.u);
195	      const k = THREE.MathUtils.lerp(kOf(Z), it.openScale, open);
196	      const c = THREE.MathUtils.lerp(cOf(Z), 1, open);
197	      point(Z, it.o, p).lerp(it.openPos, open);
198	      A4.set(
199	        k + (c - k) * T.x * T.x, (c - k) * T.x * T.y, (c - k) * T.x * T.z, 0,
200	        (c - k) * T.y * T.x, k + (c - k) * T.y * T.y, (c - k) * T.y * T.z, 0,
201	        (c - k) * T.z * T.x, (c - k) * T.z * T.y, k + (c - k) * T.z * T.z, 0,
202	        0, 0, 0, 1,
203	      );
204	      m.copy(A4).multiply(it.basis).multiply(S4.makeScale(it.s.x, it.s.y, it.s.z)).setPosition(p);
205	      mesh.setMatrixAt(i, m);
206	      ext?.setX(i, (Z - zOf(Z)) * (1 - open));
207	    });
208	    mesh.instanceMatrix.needsUpdate = true;
209	    if (ext) ext.needsUpdate = true;
210	  };
211	
212	  let lastEye = new THREE.Vector3(Infinity, 0, 0), live = true, open = 0;
213	  const eye = new THREE.Vector3();
214	  return (cam: THREE.Camera) => {
215	    eye.setFromMatrixPosition(cam.matrixWorld);
216	    if (eye.distanceToSquared(lastEye) < 1e-10) return;
217	    lastEye.copy(eye);
218	    const atLock = eye.distanceTo(eyeLock) < 2e-3;
219	    D0 = Math.max(0.5, c0.clone().sub(eye).dot(T));
220	    q.copy(eye).sub(c0).addScaledVector(T, c0.clone().sub(eye).dot(T));
221	    zs = Math.min(a.zCap, Math.max(0, D0lock - D0));
222	    if (zs < 1e-6) zs = 0;
223	    open = 1 - THREE.MathUtils.smoothstep(D0 + zs, a.foldNear, a.foldFar);
224	    if (atLock) {
225	      // the locked checkpoint eye: the build-time geometry (bit-identical locked view)
226	      if (live) { restore(); live = false; }
227	      D0 = D0lock; q.copy(ft.q); zs = 0; open = 0;
228	      ft.placeInstances(a.farRings, a.ringItems, 0);
229	      ft.placeInstances(a.farLids, a.lidItems, 0);
230	    } else {
231	      fillWall(); fillRiver();
232	      a.glow.position.copy(point(a.zEnd, o.set(0, 0, 0), p));
233	      a.glow.scale.setScalar(R * kOf(a.zEnd) * 1.35);
234	      live = true;
235	      place(a.farRings, a.ringItems, open);
236	      place(a.farLids, a.lidItems, open);
237	    }
238	    // foam behind the seam (the rising 06 banks) is clipped while the block is live (src/vfx/clip05.ts)
239	    if (atLock || open > 0.5) clip05.uClip05N.value.set(0, 0, 0);
240	    else { clip05.uClip05P.value.copy(c0).addScaledVector(T, zs); clip05.uClip05N.value.copy(T); }
241	    // `&m05seam=1` (Screen 05 round 8): the seam's course position for the near river's design hand-over (waterRibbon.ts)
242	    m05seam.value.set(sF + zs, atLock || open > 0.5 ? 0 : 1);
243	    a.farWall.morphTargetInfluences![0] = open;
244	    a.farRiver.morphTargetInfluences![0] = open;
245	    a.glowMat.uniforms.uOpacity.value = 1 - open;
246	  };
247	}
248

uniform sampler2D uPjD;    // detail (luminance high-pass, 0.5 = none), repeats in u and s
uniform vec4 uPjDS;        // tile width (u), tile length (s), gain, unused
uniform vec4 uPjFlow;      // distance (s units), rate (1/s), phase at t = 0, on
uniform vec4 uPjPost;      // exposure, saturation, contrast, vignette (the live post chain)
uniform vec2 uPjRes;       // render target size (vignette inverse)
uniform float uPjDbg;      // QA ?projdbg05=1: layer map (green = exact, blue = near, red = tile)
// ?projnear05=1 (2026-11-16, tools/proj05/near_bake.py): the HIGH-RESOLUTION near tile T2 (≈110 texels per unit
// instead of 24, mirrored repeat along s, mipmaps) takes over wherever the exact layer would be magnified while riding;
// the old tile uPjT keeps its role where E / N have no data at the locked view. uPjNear: x = on, y = share of the
// detail layer kept on T2, z = ride focus s (set every frame by vfx/index.ts), w = focus s of the locked checkpoint
uniform vec4 uPjNear;
uniform sampler2D uPjT2;   // near tile T2
uniform sampler2D uPjWT2;  // its flow map (?projflow05=2)
uniform vec2 uPjT2S;       // start s, half period L (mirrored repeat: period 2 L)
// how far ?projnear05=1 is engaged: 0 within 0.5 u of the locked checkpoint (the locked picture is the original
// proj05 one EXACTLY, including its own hand-overs), 1 from 2 u of riding on
float pjNearK() { return uPjNear.x > 0.5 ? smoothstep(0.5, 2.0, abs(uPjNear.z - uPjNear.w)) : 0.0; }
// share of the crisp near tile T2 in the near / tile layout (see ?projnear05=1 below). m05ride: every layer is read at
// the locked-view distance from Benny, so the layout under E is always the near tile (crisp) instead of the 24-texel layers
float pjT2W(float mE) {
#ifdef M05RIDE
  return pjNearK();
#else
  return pjNearK() * (1.0 - smoothstep(0.3, 0.55, mE));
#endif
}
// ?projvp05=1 (2026-11-17, session 018Sg3AU; on with ?match05=1): VARIANCE-PRESERVING hand-over while riding. A plain
// mix of two unrelated pictures of the water (exact layer E <-> crisp tile T2) halves their contrast in the hand-over
// band: the rider saw a milky, smeared band mid-river (debug map ?projdbg05=1 = the green/red cross-fade). Here each
// picture's deviation from the shared mean colour (x = on, yzw = mean of E and T2, display space) is blended and
// rescaled by 1 / sqrt(w^2 + (1-w)^2), so the band keeps the approved water's contrast. Engaged by pjNearK() only:
// at the locked checkpoint (pjNearK = 0) the picture is unchanged, pixel for pixel.
uniform vec4 uPjVP;
#ifdef M05SEAM
uniform vec2 uPjSeam;      // m05seam: (world s of the far tunnel seam, live)
#endif
#ifdef M05WD
uniform vec4 uPjWD;        // m05wd: x = on, y = share of the detail layer kept on the design, z = row smoothing (E rows)
#endif
vec3 pjMixVP(vec3 a, vec3 b, float w) {
  vec3 lin = mix(a, b, w);
  float k = uPjVP.x * pjNearK();
  if (k <= 0.0) return lin;
  vec3 mu = uPjVP.yzw;
  vec3 vp = clamp(mu + ((1.0 - w) * (a - mu) + w * (b - mu)) * inversesqrt(max(w * w + (1.0 - w) * (1.0 - w), 0.5)), 0.0, 1.0);
  return mix(lin, vp, k);
}
vec4 pjLut(float s) {
  float x = clamp((s - uPjLutS.x) / (uPjLutS.y - uPjLutS.x), 0.0, 1.0) * (uPjLutS.z - 1.0);
  float i = floor(x);
  vec4 a = texture2D(uPjLut, vec2((i + 0.5) / uPjLutS.z, 0.5));
  vec4 b = texture2D(uPjLut, vec2((min(i + 1.0, uPjLutS.z - 1.0) + 0.5) / uPjLutS.z, 0.5));
  vec4 r = mix(a, b, x - i);
  r.w = step(uPjLutS.x, s) * step(s, uPjLutS.y);
  return r;
}
// display-space target at (u, s): exact layer where it is sharp enough, else near / tile layout + detail
vec3 pjTarget(float u, float s, float mE, out float wE, out float wN) {
  vec4 L = pjLut(s);
  vec2 eUV = vec2(0.5 + (u - L.y) / (2.0 * L.z), L.x);
  vec4 e = texture2D(uPjE, eUV);
  float inE = L.w * step(0.0, eUV.x) * step(eUV.x, 1.0);
  wE = e.a * inE * smoothstep(0.3, 0.55, mE);
  #ifdef M05RIDE
  // m05ride: E's first rows hold the painted bottom gold-frame rim and wall corners (hidden by the near ring in the
  // locked view, exposed by the ride camera) and its sides end at the locked picture's edge: fade E in over those
  // rows and at its sides, the crisp near tile carries the water there
  wE *= mix(1.0, smoothstep(uPjNear.w - 1.55, uPjNear.w - 0.85, s) * smoothstep(0.0, 0.2, min(eUV.x, 1.0 - eUV.x)), pjNearK());
  #endif
  vec2 nUV = vec2(u * 0.5 + 0.5, (s - uPjNS.x) / (uPjNS.y - uPjNS.x));
  vec4 n = texture2D(uPjN, nUV);
  wN = n.a * smoothstep(0.0, 0.08, nUV.y) * (1.0 - smoothstep(0.92, 1.0, nUV.y));   // soft ends (≈3 u), no seam
  vec3 t = texture2D(uPjT, vec2(u * 0.5 + 0.5, (s - uPjTS.x) / uPjTS.y)).rgb;
  if (uPjNear.x > 0.5) {
    // ?projnear05=1: where the exact layer would be magnified, the 24-texel near layer and the old tile hand over to
    // the crisp tile T2 by the same test as E (at the locked checkpoint mE = 1.3: wT2 = 0, the locked picture is the
    // old one exactly)
    float wT2 = pjT2W(mE);
    t = pjMixVP(t, texture2D(uPjT2, vec2(u * 0.5 + 0.5, (s - uPjT2S.x) / uPjT2S.y)).rgb, wT2);
    wN *= 1.0 - wT2;
  }
  vec3 lay = mix(t, n.rgb, wN);
  if (uPjVP.x > 0.5 && pjNearK() > 0.0) {
    // E's empty texels are black and its soft edge (a < 0.5) is darkened: only well-covered texels feed the
    // variance-preserving blend (a darkened edge would otherwise be amplified into a dark fringe)
    float wEv = wE * smoothstep(0.5, 0.95, e.a) / max(e.a, 1e-3);
    wEv = mix(wE, clamp(wEv, 0.0, 1.0), pjNearK());
    wE = wEv;
    vec3 res = pjMixVP(lay, e.rgb, wE);
    #ifdef M05WD
    {
      // m05wd: the approved design E is the layout wherever it has data, smoothed along its rows
      float dv = uPjWD.z / uPjESize.y;
