      float wD = uPjWD.x * pjNearK() * inE * L.w * smoothstep(0.55, 0.95, es.a) * (1.0 - wE);
      res = mix(res, clamp(es.rgb / max(es.a, 0.55), 0.0, 1.0), wD);
      wE += wD * (1.0 - uPjWD.y);
      wN *= 1.0 - wD;
