    rideK05 = pjNearK();                         // 0 within 0.5 u of the locked checkpoint: locked picture unchanged
    s05r = s - (uPjNear.z - uPjNear.w) * rideK05;
    #ifdef M05SEAM
    if (uPjSeam.y > 0.5 && rideK05 > 0.0) {
