      float lrS = clamp(0.6 * (uPjSeam.x - uPjNear.z), 4.0, 20.0);
      float exS = clamp((uPjLutS.y - 0.6) - (uPjSeam.x - (uPjNear.z - uPjNear.w) * rideK05), 0.0, 2.0 * lrS);
      float tS = clamp((s - (uPjSeam.x - lrS)) / lrS, 0.0, 1.0);
