      float dW = 1.0 - wEx;
      float wT2m = pjT2W(mE);   // share of T2 in the tile
      dW *= 1.0 - (1.0 - wNx) * wT2m * (1.0 - uPjNear.y);
      tgt = clamp(tgt + det * uPjDS.z * dW, 0.0, 1.0);
